CREATE TYPE public.app_role AS ENUM ('admin');
CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, role public.app_role NOT NULL, UNIQUE(user_id,role));
GRANT SELECT ON public.user_roles TO authenticated;
GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.has_role(_user_id uuid,_role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_user_id AND role=_role) $$;
REVOKE ALL ON FUNCTION public.has_role(uuid,public.app_role) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.has_role(uuid,public.app_role) TO authenticated,service_role;
CREATE POLICY own_role_read ON public.user_roles FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, display_name text NOT NULL DEFAULT '' CHECK(length(display_name)<=120), timezone text NOT NULL DEFAULT 'America/New_York', updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,UPDATE ON public.profiles TO authenticated;
GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY profile_read ON public.profiles FOR SELECT TO authenticated USING(id=auth.uid());
CREATE POLICY profile_update ON public.profiles FOR UPDATE TO authenticated USING(id=auth.uid()) WITH CHECK(id=auth.uid());
CREATE FUNCTION public.create_user_profile() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.profiles(id) VALUES(NEW.id); RETURN NEW; END; $$;
CREATE TRIGGER veteran_profile_created AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.create_user_profile();
CREATE TABLE public.enquiries (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL CHECK(length(name) BETWEEN 1 AND 120), email text NOT NULL CHECK(length(email)<=180 AND email LIKE '%@%'), phone text NOT NULL CHECK(length(phone) BETWEEN 5 AND 30), zip text NOT NULL CHECK(zip ~ '^[0-9]{5}(-[0-9]{4})?$'), service text NOT NULL CHECK(length(service) BETWEEN 1 AND 120), message text NOT NULL CHECK(length(message) BETWEEN 10 AND 3000), status text NOT NULL DEFAULT 'New' CHECK(status IN ('New','In Progress','Contacted','Completed','Cancelled')), source text NOT NULL DEFAULT '/' CHECK(length(source)<=250), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.enquiries TO authenticated;
GRANT ALL ON public.enquiries TO service_role;
ALTER TABLE public.enquiries ENABLE ROW LEVEL SECURITY;
CREATE POLICY admin_enquiries ON public.enquiries FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE INDEX enquiries_date ON public.enquiries(created_at DESC);
CREATE INDEX enquiries_status ON public.enquiries(status);
CREATE TABLE public.enquiry_notes(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), enquiry_id uuid NOT NULL REFERENCES public.enquiries(id) ON DELETE CASCADE, author_id uuid NOT NULL, body text NOT NULL CHECK(length(body) BETWEEN 1 AND 3000), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,DELETE ON public.enquiry_notes TO authenticated;
GRANT ALL ON public.enquiry_notes TO service_role;
ALTER TABLE public.enquiry_notes ENABLE ROW LEVEL SECURITY;
CREATE POLICY admin_notes_read ON public.enquiry_notes FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin'));
CREATE POLICY admin_notes_insert ON public.enquiry_notes FOR INSERT TO authenticated WITH CHECK(public.has_role(auth.uid(),'admin') AND author_id=auth.uid());
CREATE POLICY admin_notes_delete ON public.enquiry_notes FOR DELETE TO authenticated USING(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.services(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), slug text NOT NULL UNIQUE CHECK(slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$'), title text NOT NULL CHECK(length(title) BETWEEN 1 AND 120), description text NOT NULL DEFAULT '' CHECK(length(description)<=6000), summary text NOT NULL DEFAULT '' CHECK(length(summary)<=1500), image_url text NOT NULL DEFAULT '', image_alt text NOT NULL DEFAULT '', enabled boolean NOT NULL DEFAULT true, display_order integer NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.services TO anon;
GRANT SELECT,INSERT,UPDATE,DELETE ON public.services TO authenticated;
GRANT ALL ON public.services TO service_role;
ALTER TABLE public.services ENABLE ROW LEVEL SECURITY;
CREATE POLICY public_services ON public.services FOR SELECT TO anon,authenticated USING(enabled);
CREATE POLICY admin_services ON public.services FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.website_content(section_key text PRIMARY KEY, label text NOT NULL, draft jsonb NOT NULL DEFAULT '{}', published jsonb NOT NULL DEFAULT '{}', updated_at timestamptz NOT NULL DEFAULT now(), published_at timestamptz);
GRANT SELECT ON public.website_content TO anon;
GRANT SELECT,INSERT,UPDATE,DELETE ON public.website_content TO authenticated;
GRANT ALL ON public.website_content TO service_role;
ALTER TABLE public.website_content ENABLE ROW LEVEL SECURITY;
CREATE POLICY admin_content ON public.website_content FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE FUNCTION public.public_website_content() RETURNS TABLE(section_key text,published jsonb) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT section_key,published FROM public.website_content $$;
REVOKE ALL ON FUNCTION public.public_website_content() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.public_website_content() TO anon,authenticated,service_role;
CREATE TABLE public.admin_activity(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), actor_id uuid, action text NOT NULL, entity text NOT NULL, entity_id text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.admin_activity TO authenticated;
GRANT ALL ON public.admin_activity TO service_role;
ALTER TABLE public.admin_activity ENABLE ROW LEVEL SECURITY;
CREATE POLICY activity_admin ON public.admin_activity FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin'));
CREATE FUNCTION public.record_admin_activity() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE row_id text; BEGIN IF TG_OP='DELETE' THEN row_id=COALESCE(to_jsonb(OLD)->>'id',to_jsonb(OLD)->>'section_key'); ELSE row_id=COALESCE(to_jsonb(NEW)->>'id',to_jsonb(NEW)->>'section_key'); END IF; INSERT INTO public.admin_activity(actor_id,action,entity,entity_id) VALUES(auth.uid(),TG_OP,TG_TABLE_NAME,row_id); IF TG_OP='DELETE' THEN RETURN OLD; END IF; IF TG_OP='UPDATE' THEN NEW.updated_at=now(); END IF; RETURN NEW; END; $$;
CREATE TRIGGER enquiry_activity BEFORE INSERT OR UPDATE OR DELETE ON public.enquiries FOR EACH ROW EXECUTE FUNCTION public.record_admin_activity();
CREATE TRIGGER service_activity BEFORE INSERT OR UPDATE OR DELETE ON public.services FOR EACH ROW EXECUTE FUNCTION public.record_admin_activity();
CREATE TRIGGER content_activity BEFORE INSERT OR UPDATE OR DELETE ON public.website_content FOR EACH ROW EXECUTE FUNCTION public.record_admin_activity();
CREATE FUNCTION public.submit_website_enquiry(p_name text,p_email text,p_phone text,p_zip text,p_service text,p_message text,p_source text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE new_id uuid; BEGIN PERFORM pg_advisory_xact_lock(hashtext(lower(p_email))); IF (SELECT count(*) FROM public.enquiries WHERE lower(email)=lower(p_email) AND created_at>now()-interval '1 hour')>=5 THEN RAISE EXCEPTION 'Too many requests. Please call the team.'; END IF; IF p_service NOT IN ('multiple','personal-training') AND NOT EXISTS(SELECT 1 FROM public.services WHERE slug=p_service AND enabled) THEN RAISE EXCEPTION 'Please select an available service.'; END IF; INSERT INTO public.enquiries(name,email,phone,zip,service,message,source) VALUES(trim(p_name),lower(trim(p_email)),trim(p_phone),trim(p_zip),p_service,trim(p_message),p_source) RETURNING id INTO new_id; RETURN new_id; END; $$;
REVOKE ALL ON FUNCTION public.submit_website_enquiry(text,text,text,text,text,text,text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.submit_website_enquiry(text,text,text,text,text,text,text) TO anon,authenticated;
CREATE FUNCTION public.admin_overview() RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY INVOKER SET search_path=public AS $$ BEGIN IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Forbidden'; END IF; RETURN jsonb_build_object('total',(SELECT count(*) FROM public.enquiries),'new',(SELECT count(*) FROM public.enquiries WHERE status='New'),'pending',(SELECT count(*) FROM public.enquiries WHERE status IN ('In Progress','Contacted')),'completed',(SELECT count(*) FROM public.enquiries WHERE status='Completed'),'services',(SELECT count(*) FROM public.services),'chart',(SELECT COALESCE(jsonb_agg(x),'[]'::jsonb) FROM (SELECT date_trunc('day',created_at)::date AS day,count(*) AS count FROM public.enquiries WHERE created_at>=current_date-29 GROUP BY 1 ORDER BY 1) x)); END; $$;
REVOKE ALL ON FUNCTION public.admin_overview() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.admin_overview() TO authenticated;